// âââ useCountUp hook âââââââââââââââââââââââââââââââââââââââââââââââ
function useCountUp(target, duration = 1600, start = false) {
  const [val, setVal] = useState(0);
  useEffect(() => {
    if (!start) return;
    let startTime = null;
    const step = (timestamp) => {
      if (!startTime) startTime = timestamp;
      const progress = Math.min((timestamp - startTime) / duration, 1);
      setVal(Math.floor(progress * target));
      if (progress < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }, [start, target, duration]);
  return val;
}

// âââ StatCard ââââââââââââââââââââââââââââââââââââââââââââââââââââââ
function StatCard({ label, value, suffix = "", prefix = "", color = D.purple, start }) {
  const count = useCountUp(value, 1600, start);
  return (
    <div style={{ background: D.card, border: `1px solid ${D.border}`, borderRadius: 12, padding: "18px 22px", flex: 1, minWidth: 130 }}>
      <div style={{ fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.06em", color: D.slate3, marginBottom: 6 }}>{label}</div>
      <div style={{ fontSize: 26, fontWeight: 800, color }}>{prefix}{count.toLocaleString()}{suffix}</div>
    </div>
  );
}

