// âââ MRRChart âââââââââââââââââââââââââââââââââââââââââââââââââââââ
function MRRChart() {
  const canvasRef = useRef(null);
  const chartRef = useRef(null);

  const months = ["M1","M2","M3","M4","M5","M6","M7","M8","M9","M10","M11","M12"];
  const mrrData = [];
  let cumulativeCustomers = 0;
  const targetMonth12 = 280;
  const churnRate = 0.035;
  const blendedARPU = 59;
  for (let m = 1; m <= 12; m++) {
    const newC = Math.floor(targetMonth12 / 78 * Math.pow(m, 1.4));
    const churned = Math.floor(cumulativeCustomers * churnRate);
    cumulativeCustomers = cumulativeCustomers + newC - churned;
    mrrData.push(Math.round(cumulativeCustomers * blendedARPU));
  }

  useEffect(() => {
    const script = document.createElement("script");
    script.src = "https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js";
    script.onload = () => {
      if (!canvasRef.current) return;
      if (chartRef.current) chartRef.current.destroy();
      chartRef.current = new window.Chart(canvasRef.current, {
        type: "line",
        data: {
          labels: months,
          datasets: [{
            label: "MRR ($)",
            data: mrrData,
            borderColor: "#6d28d9",
            backgroundColor: "#6d28d9" + "18",
            tension: 0.4,
            pointRadius: 4,
            pointBackgroundColor: "#6d28d9",
            fill: true,
          }],
        },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: { legend: { display: false } },
          scales: {
            y: { ticks: { color: "#64748b", callback: v => "$" + (v >= 1000 ? (v/1000).toFixed(0)+"k" : v) }, grid: { color: "#f0f0f0" } },
            x: { ticks: { color: "#64748b" }, grid: { color: "#f0f0f0" } },
          },
        },
      });
    };
    document.body.appendChild(script);
    return () => { if (chartRef.current) { chartRef.current.destroy(); chartRef.current = null; } };
  }, []);

  const milestones = [
    { mo: "Month 3", mrr: "$" + (mrrData[2]/1000).toFixed(1)+"k", customers: Math.round(mrrData[2]/blendedARPU) + " paying" },
    { mo: "Month 6", mrr: "$" + (mrrData[5]/1000).toFixed(1)+"k", customers: Math.round(mrrData[5]/blendedARPU) + " paying" },
    { mo: "Month 9", mrr: "$" + (mrrData[8]/1000).toFixed(1)+"k", customers: Math.round(mrrData[8]/blendedARPU) + " paying" },
    { mo: "Month 12", mrr: "$" + (mrrData[11]/1000).toFixed(1)+"k", customers: Math.round(mrrData[11]/blendedARPU) + " paying" },
  ];

  return (
    <div style={{ background: D.card, border: `1px solid ${D.border}`, borderRadius: 14, padding: 24 }}>
      <h3 style={{ margin: "0 0 16px 0", color: D.slate1, fontSize: 16, fontWeight: 700 }}>12-Month MRR Projection</h3>
      <div style={{ position: "relative", height: 260 }}>
        <canvas ref={canvasRef} />
      </div>
      <div style={{ display: "flex", gap: 12, marginTop: 18, flexWrap: "wrap" }}>
        {milestones.map(m => (
          <div key={m.mo} style={{ background: D.purpleL, borderRadius: 10, padding: "10px 16px", flex: 1, minWidth: 100 }}>
            <div style={{ fontSize: 11, color: D.purple, fontWeight: 600 }}>{m.mo}</div>
            <div style={{ fontSize: 20, fontWeight: 800, color: D.purple }}>{m.mrr}</div>
            <div style={{ fontSize: 11, color: D.slate3 }}>{m.customers}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

