              {t.popular && (
                <div style={{ position: "absolute", top: -12, left: "50%", transform: "translateX(-50%)", background: D.purple, color: "#fff", borderRadius: 20, padding: "3px 14px", fontSize: 11, fontWeight: 700, whiteSpace: "nowrap" }}>MOST POPULAR</div>
              )}
              <div style={{ fontSize: 13, fontWeight: 700, color: t.color, marginBottom: 4 }}>{t.name}</div>
              <div style={{ fontSize: 30, fontWeight: 800, color: D.slate1 }}>${price}<span style={{ fontSize: 14, fontWeight: 500, color: D.slate3 }}>/mo</span></div>
              <div style={{ fontSize: 12, color: D.slate3, marginBottom: 16 }}>{t.desc}</div>
              {t.features.map(f => (
                <div key={f} style={{ display: "flex", gap: 8, marginBottom: 7, fontSize: 12, color: D.slate2 }}>
                  <span style={{ color: D.green, fontWeight: 700 }}>â</span>{f}
                </div>
              ))}
            </div>
          );
        })}
      </div>
    </div>
  );
}

